(1, 'core', 1, 'Communication and the patient–doctor relationship', 'https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/1-communication-and-the-patient-doctor-relationship', 'Domain 1: consulting effectively, health education, cultural safety in communication, holistic patient-centred care.', '[{"title": "RACGP Curriculum unit page", "tier": 1, "url": "https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/1-communication-and-the-patient-doctor-relationship"}]', '[{"label": "RACGP patient-centred consulting models (course) gplearning", "url": "https://www.racgp.org.au/education/professional-development/online-learning/gplearning", "kind": "course"}]'),
(2, 'core', 2, 'Applied professional knowledge and skills', 'https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/2-applied-professional-knowledge-and-skills', 'Domain 2: history, examination, differential diagnoses, investigations, clinical reasoning, prescribing, procedures, uncertainty.', '[{"title": "RACGP Curriculum unit page", "tier": 1, "url": "https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/2-applied-professional-knowledge-and-skills"}]', '[{"label": "eTG complete (Therapeutic Guidelines)", "url": "https://tg.org.au", "kind": "reference"}, {"label": "Australian Medicines Handbook", "url": "https://amhonline.amh.net.au", "kind": "reference"}]'),
