(4, 'core', 4, 'Professional and ethical role', 'https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/4-professional-and-ethical-role', 'Domain 4: ethics, duty of care, professional conduct, doctor''s own health, teaching, leadership.', '[{"title": "Medical Board of Australia – Good medical practice", "tier": 1, "url": "https://www.medicalboard.gov.au/Codes-Guidelines-Policies/Code-of-conduct.aspx"}]', '[{"label": "AHPRA mandatory notification guidelines", "url": "https://www.ahpra.gov.au/", "kind": "reference"}]'),
